function appendTags(){ 
if(jQuery('[id=start-theme-css]').length==0){ 
jQuery('head').append( 
'<link ' + 
'id="start-theme-css"' + 
'rel="stylesheet"' + 
'href="https://ajax.googleapis.com/ajax/libs/jqueryui/1.10.3/themes/start/jquery-ui.min.css"' + 
'type="text/css" />' 
); 

jQuery('body').append( 

'<div id="dialog-confirm" title="Change validation owner " style="height:10px">' + 
'<p style="text-align:justify">' + 
'<img src="/s.gif" alt="validationowner" class="pageTitleIcon" title="validationowner" style="margin: 0 7px 30px 0"/>' + 
'Please select a User To Change The validation Owner.' + 
'<br/><br/>Users:' + 
'<select id="userId" style="width:300px"></select>' + 
'</p>' + 
'</div>' 
); 
jQuery('body').append( 
'<div id="dialog-sent" title="Change validation Owner">' + 
'<p style="text-align:justify">' + 
'<img src="/s.gif" alt="validationowner" class="pageTitleIcon" title="validationowner" style="margin: 0 7px 30px 0"/>' + 
'Change validation owner Successful' + 
'</p>' + 
'</div>' 
); 
jQuery('body').append( 
'<div id="Less" title="Insufficient privilege">' + 
'<p style="text-align:justify">' + 
'<img src="/s.gif" alt="validationowner" class="pageTitleIcon" title="validationowner" style="margin: 0 7px 30px 0"/>' + 
'You Dont Have privilege to change validation owner' + 
'</p>' + 
'</div>' 
); 
} 
} 

function createPopupWindow(){ 
jQuery(function() { 
jQuery( "#dialog-confirm" ).dialog({ 
autoOpen: true, 
width : "420px", 
show: { 
effect: "Bounce", 
duration:1000 


}, 

hide: { 
effect: "Explode", 
duration: 1000 
}, 
buttons: { 
"Change Owner": 
function() { 
changeowner(); 
}, 

Cancel: 
function() { 
jQuery( this ).dialog( "close" ); 
window.location.reload(); 
} 
} 
}); 
}); 
} 
function ownerchanged(){ 
jQuery(function() { 
jQuery( "#dialog-sent" ).dialog({ 
autoOpen: true, 
show: { 
effect: "Bounce", 
duration:1000 


}, 

hide: { 
effect: "Explode", 
duration: 1000 
}, 
buttons: { 
OK: 
function() { 
jQuery( this ).dialog( "close" ); 
window.location.reload(); 
} 
} 
}); 
}); 
} 
function fetchusers(){ 
var users = 
sforce.connection.query( 
'SELECT Id,Name,IsActive FROM User where IsActive = true AND (profileid = \'00e7F000000uSSj\' OR profileid=\'00e7F000000uSSk\') order by Name', 
{ 
onSuccess: 
function(result){ 
var records = result.getArray('records'); 
var innerHtml = '<option value="">--Select--</option>'; 
for(var i=0; i<records.length; i++) 
innerHtml += 
'<option value="' + records[i].Id + '">' + 
records[i].Name + 
'</option>'; 

jQuery('[id=userId]').html(innerHtml); 
}, 
onFailure: 
function(error){ 
alert('An Error has Occurred. Error: ' + error); 
} 
} 
); 
} 

function changeowner(){ 
var cvrIds = {!GETRECORDIDS( $ObjectType.Client_Validation_Request__c )}; 
var userId = jQuery('[id=userId]').val(); 
var result = sforce.apex.execute("validationChange", "userchange",{ cvr : cvrIds , uid : userId } ); 
ownerchanged(); 

} 
