function test(){ 

var acids = {!GETRECORDIDS( $ObjectType.Client_Validation_Request__c )}; 

if(acids.length === 0) 
alert('Please select atleast one record'); 
else{ 
if('{!$User.Id}'!='0057F000003Sa4x' && '{!$User.Id}'!='0057F000003RvIZ' && '{!$User.Id}'!='0057F000003SflQ'&&'{!$User.Id}'!='0057F000003Sa4P'){ 
appendTags(); 
Noaccess(); 

} 
else{ 
appendTags(); 
fetchusers(); 
createPopupWindow(); 
} 
} 
} 
test();
